window.kbPageData["views/entry/k-2637656b83b34378"] = {"key":"entry/k-2637656b83b34378","state":{"route":"entry/k-2637656b83b34378"},"node":{"id":"k-2637656b83b34378","mode":"k","title":"树立和践行正确政绩观学习教育","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"树立和践行正确政绩观学习教育","slug":"14113383a368"}],"directorySummary":"7.树立和践行正确政绩观学习教育\n2026 年 2 月，中办印发《关于在全党开展树立和践行正确政绩观学习教育的通知》，\n明确：“以立党为公、为民造福、科学决策、真抓实干为总要求，以一体推进学查改为\n抓手，教育引导各级党组织和党员、干部坚持实事求是、求真务实，为人民出政绩、以\n实干出政绩”。\n政绩观问…","sources":[{"id":"b74b1cfd8b4131c8","label":"树立和践行正确政绩观学习教育","topic":"二十届五中全会","category":"时政","text":"7.树立和践行正确政绩观学习教育\n2026 年 2 月，中办印发《关于在全党开展树立和践行正确政绩观学习教育的通知》，\n明确：“以立党为公、为民造福、科学决策、真抓实干为总要求，以一体推进学查改为\n抓手，教育引导各级党组织和党员、干部坚持实事求是、求真务实，为人民出政绩、以\n实干出政绩”。\n政绩观问题是一个根本性问题，关乎立党为公、执政为民。\n正确政绩观要求我们坚持从实际出发、按规律办事，通过科学决策和实干苦干，创\n造经得起实践和历史检验、真正造福人民、得到群众公认的业绩。\n错误政绩观则是从个人或小团体利益出发，心浮气躁、急功近利、弄虚作假、盲\n目蛮干，搞‘形象工程’、‘政绩工程’，留下包袱和隐患，引起人民群众强烈不\n满。","source":{"doc":"41195a191a57c1c36332","first":5,"last":5,"page":5,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-2637656b83b34378":[]}};
